DO $scope$
DECLARE
  endpoint_id text;
  before_schema jsonb := $before${"type":"object","required":["date","base","quote","rate"],"properties":{"base":{"enum":["EUR"],"type":"string"},"date":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$","$comment":"{\"apiosk_output_aliases_v1\":[\"source_date\"]}"},"rate":{"type":"number","minimum":1e-9,"$comment":"{\"apiosk_output_aliases_v1\":[\"exchange_rate\"]}"},"quote":{"enum":["AUD","BRL","CAD","CHF","CNY","CZK","DKK","EUR","GBP","HKD","HUF","IDR","ILS","INR","ISK","JPY","KRW","MXN","MYR","NOK","NZD","PHP","PLN","RON","SEK","SGD","THB","TRY","USD","ZAR"],"type":"string","description":"Target currency from the verified ECB daily euro reference currency set."}}}$before$::jsonb;
  after_schema jsonb := $after${"type":"object","required":["date","base","quote","rate"],"properties":{"base":{"enum":["EUR"],"type":"string"},"date":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$","$comment":"{\"apiosk_output_aliases_v1\":[\"source_date\",\"observation_date\"]}"},"rate":{"type":"number","minimum":1e-9,"$comment":"{\"apiosk_output_aliases_v1\":[\"exchange_rate\"]}"},"quote":{"enum":["AUD","BRL","CAD","CHF","CNY","CZK","DKK","EUR","GBP","HKD","HUF","IDR","ILS","INR","ISK","JPY","KRW","MXN","MYR","NOK","NZD","PHP","PLN","RON","SEK","SGD","THB","TRY","USD","ZAR"],"type":"string","description":"Target currency from the verified ECB daily euro reference currency set."}},"$comment":"{\"apiosk_fixed_scope_v1\":[{\"source_slug\":\"frankfurter\",\"method\":\"GET\",\"path\":\"/v2/providers/ecb/rate/EUR/{quote}\",\"input_facts\":[\"fx.ecb.quote\"],\"inputs\":{\"observation_date\":[\"latest\",\"most recent\",\"laatste\",\"meest recente\"],\"rate_type\":[\"official ECB reference exchange rate\",\"ECB reference exchange rate\",\"official ECB reference rate\",\"ECB reference rate\"]}}]}"}$after$::jsonb;
  annotation jsonb;
BEGIN
  IF (SELECT count(*) FROM providers.api_endpoints e JOIN providers.apis a ON a.id=e.api_id
      WHERE a.slug='frankfurter' AND e.method='GET' AND e.path='/v2/providers/ecb/rate/EUR/{quote}' AND e.active) <> 1
  THEN RAISE EXCEPTION 'Reviewed ECB endpoint identity drift'; END IF;
  SELECT e.id::text INTO STRICT endpoint_id FROM providers.api_endpoints e JOIN providers.apis a ON a.id=e.api_id
    WHERE a.slug='frankfurter' AND e.method='GET' AND e.path='/v2/providers/ecb/rate/EUR/{quote}' AND e.active;
  annotation := jsonb_set((after_schema->>'$comment')::jsonb,'{apiosk_fixed_scope_v1,0,endpoint_id}',to_jsonb(endpoint_id),true);
  after_schema := jsonb_set(after_schema,'{$comment}',to_jsonb(annotation::text));
  IF NOT EXISTS (SELECT 1 FROM catalog.fact_types WHERE slug='fx.ecb.reference_rate' AND status='active'
      AND value_schema IN (before_schema,after_schema))
  THEN RAISE EXCEPTION 'Reviewed intake schema drift: fx.ecb.reference_rate'; END IF;
  UPDATE catalog.fact_types SET value_schema=after_schema WHERE slug='fx.ecb.reference_rate' AND value_schema=before_schema;
END $scope$;

COMMIT;
